function o(e){if(!e)return null;let t=String(e).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(t))return new Date(t+"T00:00:00");/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}/.test(t)&&(t=t.replace(" ","T")),/[zZ]|[+-]\d{2}:\d{2}$/.test(t)||(t+="Z");const r=new Date(t);return isNaN(r.getTime())?null:r}function a(e){const t=o(e);if(!t)return"";const r=Math.round((Date.now()-t.getTime())/1e3);if(r<60)return"just now";if(r<3600)return`${Math.floor(r/60)}m ago`;if(r<86400)return`${Math.floor(r/3600)}h ago`;const n=Math.floor(r/86400);return n<30?`${n}d ago`:n<365?`${Math.floor(n/30)}mo ago`:`${Math.floor(n/365)}y ago`}function i(e){return e?e.replace(/_/g," ").replace(/\b\w/g,t=>t.toUpperCase()):""}function u(e){const t=Math.max(0,Math.round(Number(e||0))),r=Math.floor(t/60),n=t%60;return`${r}:${n.toString().padStart(2,"0")}`}export{u as d,a as r,i as t};
